    await expect(orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, member.userId)).rejects.toMatchObject({ reason: "pending_exists" });
    for (const operation of [orgService.acceptOwnershipHandover, orgService.declineOwnershipHandover, orgService.cancelOwnershipHandover, orgService.getPendingOwnershipHandover]) {
      await expect(operation(other.actors.owner, t.org.id)).rejects.toBeInstanceOf(TenantScopeError);
    }
    await expect(orgService.initiateOwnershipHandover(other.actors.owner, t.org.id, t.userIds.member)).rejects.toBeInstanceOf(TenantScopeError);
    await expect(orgService.acceptOwnershipHandover(t.actors.admin, t.org.id)).rejects.toMatchObject({ reason: "nothing_pending" });
    await expect(orgService.declineOwnershipHandover(t.actors.owner, t.org.id)).rejects.toMatchObject({ reason: "nothing_pending" });
  });

  it("declines and cancels offers, allowing a new offer", async () => {
    const t = await createTenant("handover-resolve");
    await orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.member);
    expect(await orgService.declineOwnershipHandover(t.actors.member, t.org.id)).toMatchObject({ status: "declined", resolvedAt: expect.any(String) });
    await orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.member);
    expect(await orgService.cancelOwnershipHandover(t.actors.owner, t.org.id)).toMatchObject({ status: "canceled", resolvedAt: expect.any(String) });
    await expect(orgService.declineOwnershipHandover(t.actors.member, t.org.id)).rejects.toMatchObject({ reason: "nothing_pending" });
    await expect(orgService.cancelOwnershipHandover(t.actors.owner, t.org.id)).rejects.toMatchObject({ reason: "nothing_pending" });
  });

  it("lapses exactly at seven days and leaves expired offers unchanged when acted on", async () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date("2026-01-01T00:00:00.000Z"));
    const t = await createTenant("handover-expiry");
    const offer = await orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.member);
    vi.setSystemTime(new Date(new Date(offer.expiresAt).getTime() - 1));
    expect(await orgService.getPendingOwnershipHandover(t.actors.viewer, t.org.id)).toEqual(offer);
    vi.setSystemTime(new Date(offer.expiresAt));
    expect(await orgService.getPendingOwnershipHandover(t.actors.viewer, t.org.id)).toBeNull();
    await expect(orgService.acceptOwnershipHandover(t.actors.member, t.org.id)).rejects.toMatchObject({ reason: "expired" });
    await expect(orgService.declineOwnershipHandover(t.actors.member, t.org.id)).rejects.toMatchObject({ reason: "expired" });
    expect(handoverRepo.findUnresolved(t.org.id)).toEqual(offer);
    const next = await orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.viewer);
    expect(next.id).not.toBe(offer.id);
  });

  it("accepts just before expiry, with only the previous owner'"'s role event when recipient is already owner\", async () => {
    vi.useFakeTimers();
    const t = await createTenant(\"handover-second-owner\");
